639	// Mini sistema de templates: tudo que é interpolado é escapado automaticamente,
640	// a não ser que venha de outro html`` ou de raw(). Isso protege contra XSS.
641	class Raw {
642	  constructor(s) {
643	    this.s = s;
644	  }
645	  toString() {
646	    return this.s;
647	  }
648	}
