652	function esc(v) {
653	  return String(v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
654	}
655	
656	function renderizar(v) {
657	  if (v === null || v === undefined || v === false) return '';
658	  if (v instanceof Raw) return v.s;
659	  if (Array.isArray(v)) return v.map(renderizar).join('');
660	  return esc(v);
661	}
