672	// Cálculo de pontos, conquistas e rankings.
673	// Tudo é calculado a partir dos dados reais: se um post ou curtida
674	// for apagado, a pontuação se ajusta sozinha.
675	const db = require('./db');
676	const { PONTOS, CONQUISTAS } = require('./regras');
677	
678	const SQL_STATS = `
679	SELECT u.id, u.nome, u.curso, u.avatar,
680	  (SELECT COUNT(*) FROM posts p WHERE p.usuario_id = u.id) AS posts,
681	  (SELECT COUNT(DISTINCT c.post_id) FROM comentarios c JOIN posts p ON p.id = c.post_id
682	     WHERE c.usuario_id = u.id AND p.usuario_id <> u.id) AS comentarios,
683	  (SELECT COUNT(*) FROM curtidas l JOIN posts p ON p.id = l.post_id
684	     WHERE p.usuario_id = u.id AND l.usuario_id <> u.id) AS curtidas,
685	  (SELECT COUNT(*) FROM medalhas m WHERE m.aluno_id = u.id) AS medalhas,
686	  (SELECT COALESCE(SUM(t.pontos), 0) FROM medalhas m JOIN tipos_medalha t ON t.id = m.tipo_id
687	     WHERE m.aluno_id = u.id) AS pontos_medalhas
688	FROM usuarios u
689	WHERE u.papel = 'aluno'`;
690	
691	function calcular(s) {
692	  const conquistas = CONQUISTAS.filter((c) => c.atingiu(s));
693	  const pontosConquistas = conquistas.reduce((soma, c) => soma + c.bonus, 0);
694	  const total =
695	    s.posts * PONTOS.post +
696	    s.comentarios * PONTOS.comentario +
697	    s.curtidas * PONTOS.curtida +
698	    s.pontos_medalhas +
699	    pontosConquistas;
700	  return { ...s, conquistas, pontos_conquistas: pontosConquistas, total };
701	}
