703	function ranking(curso) {
704	  let lista = db.prepare(SQL_STATS).all().map(calcular);
705	  if (curso) lista = lista.filter((a) => a.curso === curso);
706	  lista.sort((a, b) => b.total - a.total || a.nome.localeCompare(b.nome, 'pt-BR'));
707	  // Empatados ficam na mesma posição.
708	  lista.forEach((a, i) => {
709	    a.posicao = i > 0 && lista[i - 1].total === a.total ? lista[i - 1].posicao : i + 1;
710	  });
711	  return lista;
712	}
