714	function statsDoAluno(id) {
715	  const row = db.prepare(SQL_STATS + ' AND u.id = ?').get(id);
716	  if (!row) return null;
717	  const s = calcular(row);
718	  s.posicao_geral = ranking().find((a) => a.id === id)?.posicao;
719	  s.posicao_curso = s.curso ? ranking(s.curso).find((a) => a.id === id)?.posicao : null;
720	  return s;
721	}
722	
723	module.exports = { ranking, statsDoAluno };
724	// Regras de pontuação e conquistas do Maxx.
725	
726	// Pontos por ação.
727	const PONTOS = {
728	  post: 10, // cada post publicado
729	  comentario: 3, // por post de colega comentado (só conta 1 vez por post)
730	  curtida: 2, // cada curtida recebida de outra pessoa
731	};
732	
733	// Conquistas automáticas: quando a condição é atingida, o aluno ganha o bônus.
734	const CONQUISTAS = [
735	  { id: 'primeiro_post', emoji: '📸', nome: 'Primeiro clique', descricao: 'Publicou o primeiro post', bonus: 20, atingiu: (s) => s.posts >= 1 },
736	  { id: 'fotografo', emoji: '🎞️', nome: 'Fotógrafo do campus', descricao: 'Publicou 10 posts', bonus: 50, atingiu: (s) => s.posts >= 10 },
737	  { id: 'bom_de_papo', emoji: '💬', nome: 'Bom de papo', descricao: 'Comentou em 10 posts de colegas', bonus: 30, atingiu: (s) => s.comentarios >= 10 },
738	  { id: 'popular', emoji: '❤️', nome: 'Popular', descricao: 'Recebeu 50 curtidas', bonus: 50, atingiu: (s) => s.curtidas >= 50 },
739	  { id: 'estrela', emoji: '🌟', nome: 'Estrela da UniMax', descricao: 'Recebeu 200 curtidas', bonus: 100, atingiu: (s) => s.curtidas >= 200 },
740	  { id: 'medalhista', emoji: '🏅', nome: 'Medalhista', descricao: 'Ganhou a primeira medalha de um professor', bonus: 20, atingiu: (s) => s.medalhas >= 1 },
741	  { id: 'colecionador', emoji: '🏆', nome: 'Colecionador', descricao: 'Ganhou 5 medalhas de professores', bonus: 60, atingiu: (s) => s.medalhas >= 5 },
742	];
743	
744	// Medalhas que os professores podem dar (criadas no banco na primeira execução).
745	const MEDALHAS_PADRAO = [
746	  { nome: 'Excelência acadêmica', emoji: '🥇', pontos: 50, descricao: 'Desempenho excepcional na disciplina' },
747	  { nome: 'Projeto destaque', emoji: '🚀', pontos: 40, descricao: 'Entregou um projeto que se destacou' },
748	  { nome: 'Ideia brilhante', emoji: '💡', pontos: 30, descricao: 'Trouxe uma ideia ou solução criativa' },
749	  { nome: 'Ajudou os colegas', emoji: '🤝', pontos: 30, descricao: 'Ajudou a turma a aprender' },
750	  { nome: 'Participação em aula', emoji: '🙋', pontos: 20, descricao: 'Participou ativamente das aulas' },
751	];
752	
753	module.exports = { PONTOS, CONQUISTAS, MEDALHAS_PADRAO };
754	// Acesso da banca do TCC: permite entrar sem cadastro, com um código de acesso,
755	// em contas de teste (aluno, professor e faculdade).
756	//
757	// Fica DESLIGADO por padrão. Para ligar no dia da apresentação, inicie o app com
758	// a variável CODIGO_BANCA definida (mínimo 6 caracteres). Ao desligar, as contas
759	// de teste param de funcionar na hora, mesmo para quem já estava logado.
760	const crypto = require('node:crypto');
761	const config = require('./config');
762	const db = require('./db');
763	
764	const TAMANHO_MIN_CODIGO = 6;
765	const MAX_TENTATIVAS = 10; // tentativas erradas por IP...
766	const JANELA_MS = 15 * 60 * 1000; // ...a cada 15 minutos
767	
768	const dominio = config.DOMINIOS_PERMITIDOS[0];
769	const CONTAS = {
770	  aluno: { nome: 'Banca · Aluno(a)', email: `banca.aluno@${dominio}`, papel: 'aluno', curso: config.CURSOS[0], rotulo: 'Aluno(a)' },
771	  professor: { nome: 'Banca · Professor(a)', email: `banca.professor@${dominio}`, papel: 'professor', curso: null, rotulo: 'Professor(a)' },
772	  admin: { nome: 'Banca · Faculdade', email: `banca.faculdade@${dominio}`, papel: 'admin', curso: null, rotulo: 'Faculdade' },
773	};
774	const EMAILS = new Set(Object.values(CONTAS).map((c) => c.email));
775	
776	const ligada = () => String(config.CODIGO_BANCA || '').length >= TAMANHO_MIN_CODIGO;
777	const ehContaBanca = (email) => EMAILS.has(String(email).toLowerCase());
778	
779	if (config.CODIGO_BANCA && !ligada()) {
780	  console.warn(`CODIGO_BANCA ignorado: precisa ter pelo menos ${TAMANHO_MIN_CODIGO} caracteres.`);
781	}
782	
783	function codigoConfere(codigo) {
784	  const h = (s) => crypto.createHash('sha256').update(String(s).trim().toLowerCase()).digest();
785	  return crypto.timingSafeEqual(h(codigo), h(config.CODIGO_BANCA));
786	}
787	
788	// Limite simples de tentativas erradas por IP, para ninguém ficar chutando códigos.
789	const tentativas = new Map();
790	function bloqueado(ip) {
791	  const t = tentativas.get(ip);
792	  if (!t || Date.now() - t.inicio > JANELA_MS) return false;
793	  return t.n >= MAX_TENTATIVAS;
794	}
795	function registrarErro(ip) {
796	  const t = tentativas.get(ip);
797	  if (!t || Date.now() - t.inicio > JANELA_MS) tentativas.set(ip, { n: 1, inicio: Date.now() });
798	  else t.n++;
799	}
800	
801	// Cria a conta de teste se ainda não existir e garante que o papel está certo.
802	// A senha é inválida de propósito: só dá para entrar por aqui.
803	function obterConta(perfil) {
804	  const c = CONTAS[perfil];
805	  const existente = db.prepare('SELECT id FROM usuarios WHERE email = ?').get(c.email);
806	  if (existente) {
807	    db.prepare('UPDATE usuarios SET papel = ? WHERE id = ?').run(c.papel, existente.id);
808	    return existente.id;
809	  }
810	  const r = db
811	    .prepare('INSERT INTO usuarios (nome, email, senha_hash, papel, curso, bio) VALUES (?, ?, ?, ?, ?, ?)')
812	    .run(c.nome, c.email, '!', c.papel, c.curso, 'Conta de teste da banca do TCC');
813	  return Number(r.lastInsertRowid);
814	}
815	
816	// Retorna { usuarioId } se deu certo, ou { erro } com a mensagem para mostrar.
817	function entrar({ codigo, perfil, ip }) {
818	  if (!Object.hasOwn(CONTAS, perfil)) return { erro: 'Escolha um perfil para entrar.' };
819	  if (bloqueado(ip)) return { erro: 'Muitas tentativas. Aguarde alguns minutos e tente de novo.' };
820	  if (!codigoConfere(codigo)) {
821	    registrarErro(ip);
822	    return { erro: 'Código de acesso incorreto.' };
823	  }
824	  return { usuarioId: obterConta(perfil) };
825	}
826	
827	module.exports = { CONTAS, ligada, ehContaBanca, entrar };
828

