142	// ---------- Feed ----------
143	function cartaoPost(p, voltar) {
144	  return html`<article class="post" id="post-${p.id}">
145	  <header class="post-topo">${linkUsuario(p)}<span class="tempo">${tempoRelativo(p.criado_em)}</span></header>
