149	      : html`<a href="/posts/${p.id}" class="post-texto">${p.legenda}</a>`
150	  }
151	  <div class="post-acoes">
152	    <form method="post" action="/posts/${p.id}/curtir">
153	      <input type="hidden" name="voltar" value="${voltar}">
154	      <button class="btn-icone ${p.curti ? 'curtido' : ''}" aria-label="${p.curti ? 'Descurtir' : 'Curtir'}">${icone.coracao}</button>
155	    </form>
156	    <a class="btn-icone" href="/posts/${p.id}#comentar" aria-label="Comentar">${icone.comentario}</a>
157	  </div>
158	  <div class="post-info">
159	    <strong>${plural(p.n_curtidas, 'curtida', 'curtidas')}</strong>
160	    ${p.imagem && p.legenda ? html`<p class="legenda"><a href="/u/${p.usuario_id}"><strong>${p.nome}</strong></a> ${p.legenda}</p>` : ''}
161	    ${p.n_comentarios > 0 ? html`<a class="muted" href="/posts/${p.id}">Ver ${plural(p.n_comentarios, 'comentário', 'comentários')}</a>` : ''}
162	  </div>
163	</article>`;
164	}
