693	// Cliente simples que guarda o cookie de sessão.
694	function cliente() {
695	  let cookie = '';
696	  async function req(metodo, caminho, corpo) {
697	    const opcoes = { method: metodo, redirect: 'manual', headers: { cookie } };
698	    if (corpo instanceof FormData) opcoes.body = corpo;
699	    else if (corpo) {
700	      opcoes.body = new URLSearchParams(corpo);
701	      opcoes.headers['content-type'] = 'application/x-www-form-urlencoded';
702	    }
703	    const r = await fetch(base + caminho, opcoes);
704	    const setCookie = r.headers.get('set-cookie');
705	    if (setCookie) cookie = setCookie.split(';')[0];
706	    return { status: r.status, local: r.headers.get('location'), html: await r.text() };
707	  }
708	  return { get: (c) => req('GET', c), post: (c, corpo) => req('POST', c, corpo) };
709	}
